package clusterdata.utils;

import org.apache.flink.streaming.api.functions.source.SourceFunction;

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.zip.GZIPInputStream;
import java.nio.file.Files;
import java.nio.file.Paths;

public abstract class GzipFileSource<T> implements SourceFunction<T> {
    private volatile boolean isRunning = true;
    private String filePath;

    public GzipFileSource(String filePath) {
        this.filePath = filePath;
    }

    protected abstract T parseLine(String line);

    @Override
    public void run(SourceContext<T> ctx) throws Exception {
        try (GZIPInputStream gis = new GZIPInputStream(Files.newInputStream(Paths.get(filePath)));
             BufferedReader reader = new BufferedReader(new InputStreamReader(gis, StandardCharsets.UTF_8))) {

            String line;
            while (isRunning && (line = reader.readLine()) != null) {
                T element = parseLine(line);
                if (element != null) {
                    ctx.collect(element);
                }
            }
        }
    }

    @Override
    public void cancel() {
        isRunning = false;
    }
}

