package clusterdata.query;

import clusterdata.datatypes.TaskEvent;
import clusterdata.utils.AppBase;
import clusterdata.utils.GzipFileSource;
import clusterdata.utils.TaskEventParser;
import org.apache.flink.api.common.functions.MapFunction;
import org.apache.flink.api.common.state.MapState;
import org.apache.flink.api.common.state.MapStateDescriptor;
import org.apache.flink.api.common.state.ValueState;
import org.apache.flink.api.common.state.ValueStateDescriptor;
import org.apache.flink.api.common.typeinfo.BasicTypeInfo;
import org.apache.flink.api.common.typeinfo.TypeHint;
import org.apache.flink.api.common.typeinfo.TypeInformation;
import org.apache.flink.api.java.tuple.Tuple2;
import org.apache.flink.api.java.utils.ParameterTool;
import org.apache.flink.configuration.Configuration;
import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.KeyedProcessFunction;
import org.apache.flink.streaming.api.functions.sink.SinkFunction;
import org.apache.flink.util.Collector;

import java.io.BufferedWriter;
import java.io.File;
import java.io.FileWriter;
import java.io.IOException;

public class LongestSessionPerJob extends AppBase {

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        System.out.println("task_input  "+taskInput);
        System.out.println("job_input  "+jobInput);
        final long sesssize = params.getLong("sesssize", 600) * 1_000_000; // convert to microseconds

        // set up streaming execution environment
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        env.setParallelism(1);

        // Read task events from gzipped CSV
        DataStream<TaskEvent> taskStream = env.addSource(
            taskSourceOrTest(new GzipFileSource<TaskEvent>(taskInput) {
                @Override
                protected TaskEvent parseLine(String line) {
                    return TaskEventParser.parse(line);
                }
            })
        );

        // Filter only SUBMIT events (eventType == 0)
        DataStream<TaskEvent> submitEvents = taskStream.filter(event -> event.eventType == 0);

        // Process events to find longest stage per job
        DataStream<Tuple2<Long, Integer>> result = submitEvents
            .keyBy(event -> event.jobId)
            .process(new StageDetectionProcessFunction(sesssize));

        // Write output to file
        result.addSink(taskSinkOrTest(new FileSink(outputPath)));

        env.execute("LongestSessionPerJob");
    }

    static class StageDetectionProcessFunction extends KeyedProcessFunction<Long, TaskEvent, Tuple2<Long, Integer>> {
        private long inactivityThreshold;

        // State to track the current stage
        private transient ValueState<Integer> currentStageCountState;
        private transient ValueState<Long> lastSubmitTimeState;
        private transient ValueState<Integer> longestStageCountState;
        private transient ValueState<Long> stageStartTimeState;

        public StageDetectionProcessFunction(long inactivityThreshold) {
            this.inactivityThreshold = inactivityThreshold;
        }

        @Override
        public void open(Configuration parameters) throws Exception {
            super.open(parameters);
            currentStageCountState = getRuntimeContext().getState(
                new ValueStateDescriptor<>("currentStageCount", Integer.class));
            lastSubmitTimeState = getRuntimeContext().getState(
                new ValueStateDescriptor<>("lastSubmitTime", Long.class));
            longestStageCountState = getRuntimeContext().getState(
                new ValueStateDescriptor<>("longestStageCount", Integer.class));
            stageStartTimeState = getRuntimeContext().getState(
                new ValueStateDescriptor<>("stageStartTime", Long.class));
        }

        @Override
        public void processElement(TaskEvent event, Context ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            Long jobId = ctx.getCurrentKey();
            long timestamp = event.timestamp;

            Integer currentCount = currentStageCountState.value();
            if (currentCount == null) {
                currentCount = 0;
            }

            Long lastTime = lastSubmitTimeState.value();
            Integer longestCount = longestStageCountState.value();
            if (longestCount == null) {
                longestCount = 0;
            }

            Long stageStartTime = stageStartTimeState.value();
            if (stageStartTime == null) {
                stageStartTime = timestamp;
            }

            // Check if we've exceeded the inactivity threshold
            if (lastTime != null && (timestamp - lastTime) > inactivityThreshold) {
                // Stage ended - update longest if needed
                if (currentCount > longestCount) {
                    longestCount = currentCount;
                }
                // Start new stage
                currentCount = 1;
                stageStartTime = timestamp;
            } else {
                // Continue current stage
                currentCount++;
            }

            lastSubmitTimeState.update(timestamp);
            currentStageCountState.update(currentCount);
            longestStageCountState.update(longestCount);
            stageStartTimeState.update(stageStartTime);
        }

        @Override
        public void onTimer(long timestamp, OnTimerContext ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            // This would be called for a timer if we set one
        }
    }

    static class FileSink implements SinkFunction<Tuple2<Long, Integer>> {
        private String outputPath;
        private transient BufferedWriter writer;

        public FileSink(String outputPath) {
            this.outputPath = outputPath;
        }

        @Override
        public void invoke(Tuple2<Long, Integer> value, Context context) throws Exception {
            if (writer == null) {
                File file = new File(outputPath);
                file.getParentFile().mkdirs();
                writer = new BufferedWriter(new FileWriter(file, true));
            }
            writer.write("(" + value.f0 + "," + value.f1 + ")");
            writer.newLine();
            writer.flush();
        }

        @Override
        public void finish() throws Exception {
            if (writer != null) {
                writer.close();
            }
        }
    }

}

